// Replays the backend's own 402, quote and receipt (contract-fixtures/aifp1, generated by
// aifinpay-web test/aifp1-contract-fixtures.test.js) through the real purchase path.
import { describe, it, expect, vi, afterEach } from "vitest";
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { aifp1Fetch, Aifp1ReceiptCache, type Aifp1Deps, type Aifp1FetchOptions } from "../src/aifp1.js";
import { PAYMENT_CHAINS, type PaymentChain } from "../src/paymentChains.js";

const DIR = new URL("../../contract-fixtures/aifp1/", import.meta.url);
const read = (name: string) => readFileSync(new URL(name, DIR), "utf8");
const manifest = JSON.parse(read("MANIFEST.json")) as { files: Record<string, string> };
const json = (value: unknown, status = 200) =>
  new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });

afterEach(() => {
  vi.useRealTimers();
});

it("vendored fixtures are the ones their manifest pins", () => {
  for (const [name, digest] of Object.entries(manifest.files))
    expect(createHash("sha256").update(read(name)).digest("hex"), name).toBe(digest);
});

describe.each(Object.keys(manifest.files))("%s", (name) => {
  it("buys with the backend's real quote and accepts its real receipt", async () => {
    const f = JSON.parse(read(name));
    vi.useFakeTimers({ now: Date.parse(f.generated_at) + 1000, toFake: ["Date"] });
    const chain = f.quote.settlement_call.chain as PaymentChain;
    const asset = f.quote.settlement_call.asset as string;
    const stable = asset !== PAYMENT_CHAINS[chain].native;
    const url = f.merchant_origin + f.challenge_402.resource;
    const txRef = f.pay_response.tx_ref as string;
    const quoteBodies: unknown[] = [];
    const payBodies: Record<string, unknown>[] = [];
    const fetchImpl = vi.fn(async (input: Parameters<typeof fetch>[0], init?: RequestInit) => {
      const target = String(input);
      if (target === `${f.api_base}/v1/quote`) {
        quoteBodies.push(JSON.parse(String(init?.body)));
        return json(f.quote);
      }
      if (target === `${f.api_base}/.well-known/jwks.json`) return json({ keys: [f.issuer_jwk] });
      if (target === `${f.api_base}/v1/pay`) {
        payBodies.push(JSON.parse(String(init?.body)));
        return json({ ...f.pay_response, receipt: f.receipt_jwt_parts.join(".") });
      }
      if (target === url)
        return new Headers(init?.headers).has("AIFP-Receipt")
          ? json({ genres: ["Drama"] })
          : json(f.challenge_402, 402);
      throw new Error(`unexpected request ${target}`);
    }) as unknown as typeof fetch;
    const deps: Aifp1Deps = {
      fetchImpl,
      cache: new Aifp1ReceiptCache(),
      agentId: f.payer,
      payerAddress: f.payer,
      signPaymentAuthorization: vi.fn(async () => "0xsignature"),
      settle: vi.fn(async (p) => {
        await p.onPrepared?.({ hash: txRef, serializedTransaction: f.signed_transaction });
        return txRef;
      }),
      checkPerCall: () => true,
      reserveDaily: vi.fn(async () => "reservation"),
      commit: vi.fn(async () => {}),
      release: vi.fn(async () => {}),
      prepareReservation: vi.fn(async () => {}),
      assertReservation: vi.fn(async () => {}),
      completeReservation: vi.fn(async () => {}),
    };
    const opts: Aifp1FetchOptions = {
      gatewayOrigins: [f.merchant_origin],
      resourcePathMode: "direct",
      scope: "exact",
      maxAmountUsd: Number(f.quote.amount) + 0.01,
      ...(stable
        ? {}
        : {
            nativeUsdPrice: async () => ({ usd: Number(f.quote.native_settlement.rate_usd), observedAtMs: Date.now() }),
          }),
      v14: { chain, maxGasWei: 50000000000000000n, onPrepared: vi.fn(async () => {}), ...(stable ? { asset } : {}) },
    };

    expect((await aifp1Fetch(deps, url, {}, opts))?.status).toBe(200);
    expect(quoteBodies).toEqual([f.quote_request]);
    expect(deps.settle).toHaveBeenCalledWith(expect.objectContaining({ settlementCall: f.quote.settlement_call }));
    expect(payBodies).toHaveLength(1);
    expect(payBodies[0]).toMatchObject({ quote_id: f.quote.quote_id, chain, tx_ref: txRef });
  });
});
